    \"-q\" \\
    \"--keep-umask\" \\
    \"/tmp/tmp.J3cRKxpliwtlmksel\" \\
    \"update-tlmgr-r78218.sh\" \\
    \"TeX Live Manager Updater\" \\
    \"./runme.sh\""
